// Coffee M&A Newsletter Processor v1.1
// Especializado en fusiones, adquisiciones e inversiones en café especial
// SIN traducciones parciales para evitar Spanglish

const allItems = $input.all();
const currentDate = new Date();
const oneWeekAgo = new Date(currentDate.getTime() - 7 * 24 * 60 * 60 * 1000);

// Helpers
const fmt = (n, d=2) => (n === null || n === undefined || isNaN(n)) ? 'N/A' : parseFloat(n).toFixed(d);
const pct = (c, p) => (!p || p === 0 || !c) ? null : ((c - p) / p * 100).toFixed(2);
const clean = (t) => t ? t.replace(/<[^>]*>/g, '').replace(/&[^;]+;/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 400) : '';

// Extract hostname from URL without using URL constructor
const extractHostname = (url) => {
  if (!url) return 'Unknown';
  const match = url.match(/^(?:https?:\/\/)?(?:www\.)?([^\/:?#]+)/i);
  return match ? match[1] : 'Unknown';
};

// Palabras clave para M&A (en inglés y español para detección)
const maKeywords = [
  'acquisition', 'acquires', 'acquired', 'acquire',
  'merger', 'merge', 'merged', 'merging',
  'investment', 'invests', 'invested', 'investor',
  'funding', 'funded', 'raises', 'raised',
  'series a', 'series b', 'series c', 'seed round',
  'private equity', 'venture capital', 'vc',
  'buyout', 'buy out', 'bought',
  'partnership', 'partners', 'joint venture',
  'expansion', 'expands', 'expanding',
  'sale', 'sells', 'sold', 'selling',
  'ipo', 'public offering', 'spac',
  'valuation', 'valued at',
  'stake', 'shares', 'equity',
  'deal', 'transaction', 'agreement',
  'convertible', 'notes', 'debt', 'financing',
  'adquisición', 'adquiere', 'fusión', 'inversión',
  'financiamiento', 'expansión', 'compra', 'venta'
];

// Compañías relevantes para seguimiento
const relevantCompanies = [
  'westrock', 'jab holding', 'jde peets', 'starbucks', 'nestle', 'nespresso',
  'blue bottle', 'intelligentsia', 'stumptown', 'counter culture',
  'la colombe', 'dunkin', 'peets', 'lavazza', 'illy', 'illycaffè',
  'keurig', 'dr pepper', 'green mountain', 'caribou',
  'tim hortons', 'costa coffee', 'luckin',
  'libertario', 'la palma', 'tucan', 'devocion', 'onyx coffee',
  'verve', 'ritual', 'sightglass', 'equator', 'klatch',
  'george howell', 'bird rock', 'proud mary', 'sey',
  'cafe imports', 'royal coffee', 'genuine origin', 'sucafina',
  'olam', 'ecom', 'neumann kaffee', 'volcafe'
];

// Etiquetas de categoría en español (para mostrar en el reporte)
const categoryLabels = {
  acquisitions: 'Adquisición',
  mergers: 'Fusión',
  investments: 'Inversión',
  expansions: 'Expansión',
  partnerships: 'Alianza',
  public_markets: 'Mercado Público',
  divestitures: 'Desinversión',
  general: 'General'
};

// Función para calcular relevancia de M&A
const calculateMARelevance = (text) => {
  const lowerText = text.toLowerCase();
  let score = 0;

  // Puntos por palabras clave de M&A
  maKeywords.forEach(keyword => {
    if (lowerText.includes(keyword)) score += 10;
  });

  // Puntos extra por compañías relevantes
  relevantCompanies.forEach(company => {
    if (lowerText.includes(company)) score += 15;
  });

  // Puntos por menciones de montos
  if (lowerText.match(/\$\d+/)) score += 5;
  if (lowerText.match(/million|billion|millones|mil millones/)) score += 5;

  return score;
};

// Categorización de noticias
const categorizeNews = (text) => {
  const lower = text.toLowerCase();

  if (lower.match(/acquisition|acquires|acquired|buyout|bought|compra|adquiere/)) return 'acquisitions';
  if (lower.match(/merger|merge|fusion|fusión/)) return 'mergers';
  if (lower.match(/investment|invests|funding|raises|series|seed|venture|inversión|financiamiento/)) return 'investments';
  if (lower.match(/expansion|expands|opens|launch|new location|expansión/)) return 'expansions';
  if (lower.match(/partnership|partners|joint venture|alliance|alianza/)) return 'partnerships';
  if (lower.match(/ipo|public|spac|stock|shares|bolsa/)) return 'public_markets';
  if (lower.match(/sale|sells|sold|divest|venta|vende/)) return 'divestitures';

  return 'general';
};

// Data structure
const data = {
  reportDate: currentDate.toLocaleDateString('es-CO', { 
    weekday: 'long', 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric',
    timeZone: 'America/Bogota' 
  }),
  weekRange: {
    start: oneWeekAgo.toLocaleDateString('es-CO', { month: 'short', day: 'numeric' }),
    end: currentDate.toLocaleDateString('es-CO', { month: 'short', day: 'numeric' })
  },
  markets: {
    coffeeArabica: null,
    coffeeRobusta: null,
    trm: null
  },
  news: {
    acquisitions: [],
    mergers: [],
    investments: [],
    expansions: [],
    partnerships: [],
    public_markets: [],
    divestitures: [],
    general: [],
    all_ma: [],
    top_stories: []
  },
  companies: {
    mentioned: {},
    deals_count: 0
  },
  summaries: {},
  statistics: {
    totalSources: allItems.length,
    maNewsCount: 0,
    totalDealsValue: 'Por determinar'
  }
};

// Process items
allItems.forEach(item => {
  const j = item.json;

  // Yahoo Finance Coffee Futures
  if (j?.chart?.result?.[0]) {
    const c = j.chart.result[0], m = c.meta, q = c.indicators?.quote?.[0];
    if (m && q) {
      const i = (q.close?.length || 1) - 1;
      const price = q.close?.[i], prev = m.chartPreviousClose || m.previousClose || q.close?.[i-1];
      const chg = price && prev ? price - prev : null;
      const chgPct = pct(price, prev);
      const mk = {
        price: fmt(price),
        change: chg !== null ? fmt(chg) : 'N/A',
        changePercent: chgPct ? chgPct + '%' : 'N/A',
        isPositive: chg > 0,
        isNegative: chg < 0
      };
      const s = m.symbol || '';
      if (s === 'KC=F' || s.includes('KC')) {
        data.markets.coffeeArabica = { ...mk, name: 'Café Arábica (ICE)' };
      }
    }
  }

  // TRM Colombia
  if (Array.isArray(j) && j[0]?.valor) {
    const trmValue = parseFloat(j[0].valor);
    data.markets.trm = {
      rate: trmValue,
      formatted: fmt(trmValue, 2),
      date: j[0].vigenciadesde || ''
    };
  }

  // RSS News Processing
  if (j?.title && (j?.link || j?.url)) {
    const rawContent = (j.title || '') + ' ' + (j.summary || j.description || j.contentSnippet || j.content || '');
    const maRelevance = calculateMARelevance(rawContent);

    // Solo procesar noticias con relevancia de M&A
    if (maRelevance > 0) {
      const summary = clean(j.summary || j.description || j.contentSnippet || j.content || '');
      const pubDate = j.pubDate || j.isoDate || '';
      const newsDate = new Date(pubDate);

      // Solo incluir noticias de la última semana
      if (newsDate >= oneWeekAgo || !pubDate) {
        const category = categorizeNews(rawContent);

        const news = {
          title: j.title?.slice(0, 200),
          link: j.link || j.url,
          source: j.source || j.creator || extractHostname(j.link || j.url),
          pubDate: pubDate,
          summary: summary,
          relevance: maRelevance,
          category: category,
          categoryLabel: categoryLabels[category] || 'General'
        };

        // Agregar a categoría correspondiente
        if (data.news[category]) {
          data.news[category].push(news);
        }
        data.news.all_ma.push(news);

        // Rastrear compañías mencionadas
        relevantCompanies.forEach(company => {
          if (rawContent.toLowerCase().includes(company)) {
            data.companies.mentioned[company] = (data.companies.mentioned[company] || 0) + 1;
          }
        });
      }
    }
  }
});

// Sort by relevance and limit
const sortByRelevance = (arr, n) => arr
  .filter(x => x.title)
  .sort((a, b) => b.relevance - a.relevance || new Date(b.pubDate || 0) - new Date(a.pubDate || 0))
  .slice(0, n);

data.news.acquisitions = sortByRelevance(data.news.acquisitions, 10);
data.news.mergers = sortByRelevance(data.news.mergers, 5);
data.news.investments = sortByRelevance(data.news.investments, 10);
data.news.expansions = sortByRelevance(data.news.expansions, 8);
data.news.partnerships = sortByRelevance(data.news.partnerships, 5);
data.news.public_markets = sortByRelevance(data.news.public_markets, 5);
data.news.divestitures = sortByRelevance(data.news.divestitures, 5);
data.news.general = sortByRelevance(data.news.general, 5);
data.news.top_stories = sortByRelevance(data.news.all_ma, 5);

// Generate summaries (sin traducciones parciales)
const genSummary = (newsArr, defaultMsg) => {
  if (!newsArr || newsArr.length === 0) return defaultMsg;

  const topNews = newsArr.slice(0, 3);
  let parts = topNews.map(n => {
    let text = n.summary && n.summary.length > 30 ? n.summary : n.title;
    return text.replace(/\.+$/, '').trim();
  }).filter(t => t.length > 0);

  let summary = parts.join('. ');
  if (summary && !summary.endsWith('.')) summary += '.';

  if (summary.length > 500) {
    summary = summary.substring(0, 500);
    const lastSpace = summary.lastIndexOf(' ');
    if (lastSpace > 400) summary = summary.substring(0, lastSpace) + '...';
  }

  return summary || defaultMsg;
};

// Market summary
const coffee = data.markets.coffeeArabica;
let marketSummary = '';
if (coffee) {
  const dir = coffee.isPositive ? 'subió' : coffee.isNegative ? 'bajó' : 'se mantuvo estable';
  marketSummary = `El precio del Café Arábica ${dir} ${coffee.changePercent} esta semana, cerrando en $${coffee.price}/lb.`;
}
if (data.markets.trm) {
  marketSummary += ` TRM Colombia: $${data.markets.trm.formatted} COP/USD.`;
}
data.summaries.markets = marketSummary || 'Datos de mercado no disponibles.';

// News summaries by category
data.summaries.acquisitions = genSummary(data.news.acquisitions, 'No se reportaron adquisiciones significativas esta semana.');
data.summaries.investments = genSummary(data.news.investments, 'No se reportaron nuevas inversiones esta semana.');
data.summaries.expansions = genSummary(data.news.expansions, 'No se reportaron expansiones significativas esta semana.');
data.summaries.topStories = genSummary(data.news.top_stories, 'No hay noticias destacadas de M&A esta semana.');

// Executive summary
const totalMANews = data.news.all_ma.length;
const topCompanies = Object.entries(data.companies.mentioned)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([name]) => name.charAt(0).toUpperCase() + name.slice(1));

data.summaries.executive = `Esta semana se identificaron ${totalMANews} noticias relacionadas con M&A en la industria del café especial. ` +
  (data.news.acquisitions.length > 0 ? `Se reportaron ${data.news.acquisitions.length} adquisiciones. ` : '') +
  (data.news.investments.length > 0 ? `Se identificaron ${data.news.investments.length} movimientos de inversión. ` : '') +
  (topCompanies.length > 0 ? `Compañías más mencionadas: ${topCompanies.join(', ')}.` : '');

// Stats
data.statistics.maNewsCount = totalMANews;
data.companies.deals_count = data.news.acquisitions.length + data.news.mergers.length;

return [data];

// Coffee M&A Newsletter HTML Template v1.1
// Diseño profesional enfocado en M&A de café especial
// SIN traducciones parciales - contenido en idioma original

const data = $input.item.json;
const reportDate = data.reportDate || new Date().toLocaleDateString('es-CO', { 
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'America/Bogota' 
});

// Category icons and names
const categoryIcons = {
  acquisitions: '🏷️',
  mergers: '🤝',
  investments: '💰',
  expansions: '📈',
  partnerships: '🔗',
  public_markets: '📊',
  divestitures: '📤'
};

const categoryNames = {
  acquisitions: 'Adquisiciones',
  mergers: 'Fusiones',
  investments: 'Inversiones y Financiamiento',
  expansions: 'Expansiones',
  partnerships: 'Alianzas Estratégicas',
  public_markets: 'Mercados Públicos',
  divestitures: 'Desinversiones'
};

// Helper functions
const newsHtml = (items, msg, showSummary = true, showCategory = false) => {
  if (!items?.length) return `<p style="color:#6c757d;font-style:italic;padding:10px;">${msg}</p>`;

  return '<div style="margin:0;">' + items.map(n => `
    <div style="padding:12px 0;border-bottom:1px solid #e9ecef;">
      <a href="${n.link}" style="color:#1a5f2a;text-decoration:none;font-weight:600;font-size:14px;line-height:1.4;display:block;" target="_blank">
        ${n.title}
      </a>
      ${showCategory && n.categoryLabel ? `<span style="display:inline-block;background:#e8f5e9;color:#1a5f2a;padding:2px 8px;border-radius:10px;font-size:10px;margin-top:4px;">${n.categoryLabel}</span>` : ''}
      ${showSummary && n.summary ? `<p style="margin:6px 0 0;font-size:12px;color:#495057;line-height:1.5;">${n.summary.slice(0, 200)}${n.summary.length > 200 ? '...' : ''}</p>` : ''}
      <div style="margin-top:6px;font-size:11px;color:#888;">
        <span>${n.source || 'Fuente desconocida'}</span>
        ${n.pubDate ? ` • ${new Date(n.pubDate).toLocaleDateString('es-CO', { month: 'short', day: 'numeric' })}` : ''}
        ${n.relevance ? ` • Relevancia: ${'⭐'.repeat(Math.min(Math.floor(n.relevance/20), 5))}` : ''}
      </div>
    </div>
  `).join('') + '</div>';
};

const summaryBox = (text, bgColor = '#e8f5e9', borderColor = '#1a5f2a') => `
<div style="background:${bgColor};border-radius:8px;padding:14px 16px;margin-bottom:15px;border-left:4px solid ${borderColor};">
  <p style="margin:0;font-size:13px;color:#1a1a1a;line-height:1.6;"><strong>📌 Resumen:</strong> ${text}</p>
</div>`;

const sectionHeader = (icon, title, borderColor = '#1a5f2a') => `
<h2 style="color:#1a1a1a;font-size:16px;margin:25px 0 12px;padding-bottom:8px;border-bottom:3px solid ${borderColor};">
  ${icon} ${title}
</h2>`;

const coffee = data.markets?.coffeeArabica || {};
const trm = data.markets?.trm || {};
const news = data.news || {};
const sum = data.summaries || {};
const stats = data.statistics || {};
const companies = data.companies || {};

// Top mentioned companies
const topCompanies = Object.entries(companies.mentioned || {})
  .sort((a, b) => b[1] - a[1])
  .slice(0, 8)
  .map(([name, count]) => `<span style="display:inline-block;background:#f8f9fa;padding:4px 10px;margin:3px;border-radius:15px;font-size:11px;color:#495057;">${name.charAt(0).toUpperCase() + name.slice(1)} <strong>(${count})</strong></span>`)
  .join('');

const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
</head>
<body style="margin:0;padding:0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif;background:#f5f5f5;">
<div style="max-width:700px;margin:0 auto;background:#fff;">

<!-- Header -->
<div style="background:linear-gradient(135deg,#1a5f2a 0%,#2d8a3e 50%,#3da352 100%);padding:30px 25px;text-align:center;">
  <div style="color:#c8e6c9;font-size:10px;letter-spacing:3px;font-weight:700;text-transform:uppercase;">SPECIALTY COFFEE INTELLIGENCE</div>
  <h1 style="color:#fff;margin:10px 0 5px;font-size:24px;font-weight:700;">☕ M&A Weekly Report</h1>
  <p style="color:rgba(255,255,255,0.9);margin:5px 0;font-size:14px;">Fusiones, Adquisiciones e Inversiones en Café Especial</p>
  <p style="color:rgba(255,255,255,0.7);margin:8px 0 0;font-size:12px;">${reportDate}</p>
  <p style="color:rgba(255,255,255,0.6);margin:5px 0 0;font-size:11px;">Semana del ${data.weekRange?.start || ''} al ${data.weekRange?.end || ''}</p>
</div>

<!-- Stats Banner -->
<div style="background:#2d8a3e;padding:12px 20px;display:flex;justify-content:space-around;flex-wrap:wrap;">
  <div style="text-align:center;padding:5px 15px;">
    <div style="color:rgba(255,255,255,0.7);font-size:10px;text-transform:uppercase;">Noticias M&A</div>
    <div style="color:#fff;font-size:22px;font-weight:700;">${stats.maNewsCount || 0}</div>
  </div>
  <div style="text-align:center;padding:5px 15px;">
    <div style="color:rgba(255,255,255,0.7);font-size:10px;text-transform:uppercase;">Adquisiciones</div>
    <div style="color:#fff;font-size:22px;font-weight:700;">${news.acquisitions?.length || 0}</div>
  </div>
  <div style="text-align:center;padding:5px 15px;">
    <div style="color:rgba(255,255,255,0.7);font-size:10px;text-transform:uppercase;">Inversiones</div>
    <div style="color:#fff;font-size:22px;font-weight:700;">${news.investments?.length || 0}</div>
  </div>
  <div style="text-align:center;padding:5px 15px;">
    <div style="color:rgba(255,255,255,0.7);font-size:10px;text-transform:uppercase;">Fuentes</div>
    <div style="color:#fff;font-size:22px;font-weight:700;">${stats.totalSources || 0}</div>
  </div>
</div>

<!-- Executive Summary -->
<div style="background:linear-gradient(135deg,#fff8e1,#ffecb3);padding:20px 25px;border-bottom:3px solid #ffc107;">
  <h3 style="margin:0 0 10px;font-size:15px;color:#795548;">⚡ RESUMEN EJECUTIVO</h3>
  <p style="margin:0;font-size:14px;color:#5d4037;line-height:1.7;">${sum.executive || 'Resumen no disponible.'}</p>
</div>

<!-- Market Context -->
<div style="padding:15px 25px;background:#fafafa;border-bottom:1px solid #e0e0e0;">
  <h3 style="margin:0 0 10px;font-size:13px;color:#666;text-transform:uppercase;letter-spacing:1px;">📊 Contexto de Mercado</h3>
  <div style="display:flex;flex-wrap:wrap;gap:15px;">
    ${coffee.price ? `
    <div style="background:#fff;padding:12px 15px;border-radius:8px;border-left:4px solid #1a5f2a;flex:1;min-width:150px;">
      <div style="font-size:11px;color:#666;">Café Arábica (ICE)</div>
      <div style="font-size:20px;font-weight:700;color:#1a5f2a;">$${coffee.price}/lb</div>
      <div style="font-size:12px;color:${coffee.isPositive ? '#28a745' : coffee.isNegative ? '#dc3545' : '#666'};">
        ${coffee.isPositive ? '▲' : coffee.isNegative ? '▼' : '—'} ${coffee.changePercent || 'N/A'}
      </div>
    </div>` : ''}
    ${trm.formatted ? `
    <div style="background:#fff;padding:12px 15px;border-radius:8px;border-left:4px solid #667eea;flex:1;min-width:150px;">
      <div style="font-size:11px;color:#666;">TRM Colombia</div>
      <div style="font-size:20px;font-weight:700;color:#667eea;">$${trm.formatted}</div>
      <div style="font-size:11px;color:#888;">COP por USD</div>
    </div>` : ''}
  </div>
</div>

<div style="padding:20px 25px;">

<!-- Top Stories -->
${sectionHeader('🔥', 'NOTICIAS DESTACADAS DE LA SEMANA', '#dc3545')}
${summaryBox(sum.topStories || 'Sin resumen disponible.', '#ffebee', '#dc3545')}
${newsHtml(news.top_stories, 'No hay noticias destacadas esta semana.', true, true)}

<!-- Acquisitions -->
${news.acquisitions?.length > 0 ? `
${sectionHeader('🏷️', 'ADQUISICIONES', '#1a5f2a')}
${summaryBox(sum.acquisitions || 'Sin resumen disponible.', '#e8f5e9', '#1a5f2a')}
${newsHtml(news.acquisitions, 'No se reportaron adquisiciones.')}
` : ''}

<!-- Investments -->
${news.investments?.length > 0 ? `
${sectionHeader('💰', 'INVERSIONES Y FINANCIAMIENTO', '#ff9800')}
${summaryBox(sum.investments || 'Sin resumen disponible.', '#fff3e0', '#ff9800')}
${newsHtml(news.investments, 'No se reportaron inversiones.')}
` : ''}

<!-- Expansions -->
${news.expansions?.length > 0 ? `
${sectionHeader('📈', 'EXPANSIONES', '#2196f3')}
${summaryBox(sum.expansions || 'Sin resumen disponible.', '#e3f2fd', '#2196f3')}
${newsHtml(news.expansions, 'No se reportaron expansiones.')}
` : ''}

<!-- Partnerships -->
${news.partnerships?.length > 0 ? `
${sectionHeader('🔗', 'ALIANZAS ESTRATÉGICAS', '#9c27b0')}
${newsHtml(news.partnerships, 'No se reportaron alianzas.')}
` : ''}

<!-- Mergers -->
${news.mergers?.length > 0 ? `
${sectionHeader('🤝', 'FUSIONES', '#00bcd4')}
${newsHtml(news.mergers, 'No se reportaron fusiones.')}
` : ''}

<!-- Public Markets -->
${news.public_markets?.length > 0 ? `
${sectionHeader('📊', 'MERCADOS PÚBLICOS / IPOs', '#607d8b')}
${newsHtml(news.public_markets, 'No hay noticias de mercados públicos.')}
` : ''}

<!-- Companies Radar -->
${topCompanies ? `
<div style="margin-top:25px;padding:15px;background:#f8f9fa;border-radius:8px;">
  <h3 style="margin:0 0 10px;font-size:13px;color:#666;">🎯 EMPRESAS EN EL RADAR</h3>
  <p style="font-size:11px;color:#888;margin:0 0 10px;">Compañías más mencionadas esta semana:</p>
  <div style="line-height:2;">${topCompanies}</div>
</div>` : ''}

<!-- Libertario Reference -->
<div style="margin-top:25px;padding:15px;background:linear-gradient(135deg,#1a5f2a,#2d8a3e);border-radius:8px;">
  <p style="margin:0;font-size:12px;color:rgba(255,255,255,0.9);text-align:center;">
    ☕ Este reporte está diseñado para dar seguimiento a movimientos de M&A relevantes para<br>
    <strong style="color:#fff;">Libertario Coffee Roasters</strong> y empresas similares en café especial.
  </p>
</div>

</div>

<!-- Footer -->
<div style="background:#1a1a1a;padding:25px;text-align:center;">
  <p style="color:#1a5f2a;font-size:13px;margin:0;font-weight:600;">Coffee M&A Intelligence v1.0</p>
  <p style="color:#888;font-size:11px;margin:8px 0;">📰 ${stats.maNewsCount || 0} noticias analizadas | 🔍 ${stats.totalSources || 0} fuentes monitoreadas</p>
  <p style="color:#666;font-size:10px;margin:10px 0 0;">
    ⚠️ Este informe es solo informativo. No constituye asesoría de inversión.<br>
    Las noticias son recopiladas automáticamente de fuentes públicas.
  </p>
</div>

</div>
</body>
</html>`;

// Generate email subject
